#!/usr/bin/env node

/**
 * quick-pass-cli
 * A lightweight, zero-dependency CLI tool to generate secure passwords.
 * Built using Node.js's native 'crypto' module for cryptographic security.
 */

const crypto = require('crypto');

// 1. Define character pools used to build the password
const UPPERCASE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const LOWERCASE = 'abcdefghijklmnopqrstuvwxyz';
const NUMBERS = '0123456789';
const SYMBOLS = '!@#$%^&*()_+-=[]{}|;:,.<>?';

// Combine all characters into one pool for the remaining characters
const ALL_CHARS = UPPERCASE + LOWERCASE + NUMBERS + SYMBOLS;

/**
 * Generates a random, secure password of the specified length.
 * Uses crypto.randomInt to avoid bias from Math.random().
 * 
 * @param {number} length - Desired length of the password.
 * @returns {string} - The generated password.
 */
function generatePassword(length) {
  // Ensure the password includes at least one character from each character set
  const passwordChars = [
    UPPERCASE[crypto.randomInt(0, UPPERCASE.length)],
    LOWERCASE[crypto.randomInt(0, LOWERCASE.length)],
    NUMBERS[crypto.randomInt(0, NUMBERS.length)],
    SYMBOLS[crypto.randomInt(0, SYMBOLS.length)]
  ];

  // Fill the remaining length with random characters from the combined pool
  for (let i = passwordChars.length; i < length; i++) {
    const randomIndex = crypto.randomInt(0, ALL_CHARS.length);
    passwordChars.push(ALL_CHARS[randomIndex]);
  }

  // Shuffle the array using the Fisher-Yates algorithm
  // This ensures the first four required characters aren't in a predictable order
  for (let i = passwordChars.length - 1; i > 0; i--) {
    const j = crypto.randomInt(0, i + 1);
    [passwordChars[i], passwordChars[j]] = [passwordChars[j], passwordChars[i]];
  }

  return passwordChars.join('');
}

/**
 * Main entry point for the CLI script.
 */
function main() {
  const args = process.argv.slice(2);

  // Check for help flags
  if (args.includes('--help') || args.includes('-h')) {
    console.log(`
Usage:
  quick-pass [length]

Options:
  -h, --help    Show this help message

Examples:
  quick-pass        Generates a 12-character password (default)
  quick-pass 16     Generates a 16-character password
    `);
    process.exit(0);
  }

  // Read length from CLI arguments or default to 12
  const inputLength = args[0] ? parseInt(args[0], 10) : 12;

  // Input validation
  if (isNaN(inputLength) || inputLength <= 0) {
    console.error('Error: Password length must be a positive integer.');
    process.exit(1);
  }

  if (inputLength < 4) {
    console.error('Error: Minimum password length is 4 (to include uppercase, lowercase, number, and symbol).');
    process.exit(1);
  }

  // Generate and print the password
  const password = generatePassword(inputLength);

  console.log('\nGenerated Password:');
  console.log(`  ${password}\n`);
}

// Run the script
main();
